const item = $input.first();
const body = item.json.body ?? item.json;
const state = {request_id: `bcmid-${Date.now()}-${Math.random().toString(36).slice(2)}`, question:'',query:'',patient_id:null,filters:{split:'train'},intent:'out_of_scope_or_insufficient',tools:[],needs_generation:false,retry_count:0,status:'pending',reports:[],images:[],metadata:[],registry:[],generation_evidence:[],candidate_answer:'',answer:null,citations:[],checker:{decision:'not_checked',problems:[],checked_passage_ids:[]},tools_called:[],trace:['normalize'],limitations:['Research similar-case retrieval; no diagnosis of the query patient. Patient-level image/report links are not verified for the exact examination. Similarity is not confidence.'],errors:[]};
let image_base64=''; let requested_intent=null; let retrieve_only=false;
try {
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw Error('Request must be an object');
  const allowed=['question','patient_id','intent','filters','filters_json','retrieve_only','image_base64'];
  if(Object.keys(body).some(k=>!allowed.includes(k))) throw Error('Unknown request field');
  if(body.question!=null && typeof body.question!=='string') throw Error('question must be text');
  state.question=(body.question??'').trim(); state.query=state.question;
  if(state.question.length>2000) throw Error('question exceeds 2000 characters');
  if(body.patient_id!=null && typeof body.patient_id!=='string') throw Error('patient_id must be text');
  state.patient_id=(body.patient_id??'').trim()||null;
  if(state.patient_id && !/^[A-Za-z0-9_-]{1,128}$/.test(state.patient_id)) throw Error('Invalid patient_id');
  let f=body.filters ?? body.filters_json ?? {};
  if(typeof f==='string') f=JSON.parse(f);
  if(!f || typeof f!=='object' || Array.isArray(f)) throw Error('filters must be an object');
  const keys=['patient_id','image_id','modality','split','has_report','has_structured_report','birads'];
  if(Object.keys(f).some(k=>!keys.includes(k))) throw Error('Unknown filter');
  if(f.split!=null && f.split!=='train') throw Error('Serving tools only expose the train split');
  if(f.modality!=null && !['Mammogram','Ultrasound'].includes(f.modality)) throw Error('Invalid modality');
  for(const k of ['has_report','has_structured_report']) if(f[k]!=null && typeof f[k]!=='boolean') throw Error(`${k} must be boolean`);
  for(const k of ['patient_id','image_id']) if(f[k]!=null && (typeof f[k]!=='string'||!/^[A-Za-z0-9_-]{1,128}$/.test(f[k]))) throw Error(`Invalid ${k}`);
  if(f.birads!=null && (typeof f.birads!=='string'||!/^[0-6][a-cA-C]?$/.test(f.birads))) throw Error('Invalid BI-RADS filter');
  state.filters={...f,split:'train'};
  requested_intent=body.intent||null;
  if(requested_intent && typeof requested_intent!=='string') throw Error('intent must be text');
  if(body.retrieve_only!=null && ![true,false,'true','false'].includes(body.retrieve_only)) throw Error('Invalid retrieve_only');
  retrieve_only=body.retrieve_only===true||body.retrieve_only==='true';
  const binaries=Object.keys(item.binary??{});
  if(binaries.length>1) throw Error('Upload one image');
  if(binaries.length) {
    const buffer=await this.helpers.getBinaryDataBuffer(0,binaries[0]);
    if(buffer.length>20971520) throw Error('Image exceeds 20 MiB');
    image_base64=buffer.toString('base64');
  } else {
    image_base64=body.image_base64??'';
    if(typeof image_base64!=='string'||image_base64.length>27962028|| (image_base64 && !/^[A-Za-z0-9+/]*={0,2}$/.test(image_base64))) throw Error('Invalid image_base64');
  }
} catch(e) {state.status='invalid_request';state.errors=[e.message];image_base64='';}
return [{json:{state,image_base64,requested_intent,retrieve_only,has_image:!!image_base64}}];

const x=$input.first().json, s=x.state;
const q=s.question.toLowerCase();
const diagnosis=/\b(diagnos\w*|do i have|do they have|does (this|the) (image|patient).*cancer|is (this|it).*cancer|is my.*malignant|am i.*cancer|assess.*bi.?rads|assign.*bi.?rads)\b/i.test(q);
if(s.status==='invalid_request'||diagnosis) {s.intent='out_of_scope_or_insufficient';if(diagnosis)s.limitations.push('Diagnostic requests and BI-RADS assignment are outside this retrieval demo.');}
else if(x.requested_intent) s.intent=x.requested_intent;
else if(Object.keys(s.filters).some(k=>k!=='split' && (k!=='modality'||!x.has_image)) || /\b(metadata|patient id|patient identifier|lookup patient|find patient)\b/.test(q)) s.intent='metadata_lookup';
else if(x.has_image && (!q || /^(find |show |search |retrieve )?(similar|matching) (images|cases)/.test(q))) s.intent='image_search';
else if(x.has_image && /report|follow.?up|birads|bi-rads|finding|opinion/.test(q)) s.intent='image_and_report_question';
else if(!x.has_image && /report|follow.?up|birads|bi-rads|finding|opinion/.test(q)) s.intent='report_question';
else s.intent='out_of_scope_or_insufficient';
s.tools=({report_question:['report_search'],image_search:['image_search'],image_and_report_question:['report_search','image_search'],metadata_lookup:['metadata_lookup'],out_of_scope_or_insufficient:[]})[s.intent]??[];
s.needs_generation=!x.retrieve_only && ['report_question','image_and_report_question'].includes(s.intent) && /follow.?up|bi.?rads/i.test(q);
if(s.intent==='metadata_lookup' && !s.filters.patient_id && s.patient_id) s.filters.patient_id=s.patient_id;
s.trace.push('deterministic_classification');
return [{json:x}];

const x=$input.first().json,s=x.state;
const allowed={report_question:['report_search'],image_search:['image_search'],image_and_report_question:['report_search','image_search'],metadata_lookup:['metadata_lookup'],out_of_scope_or_insufficient:[]};
try {
 if(!(s.intent in allowed)||JSON.stringify(s.tools)!==JSON.stringify(allowed[s.intent])) throw Error('Unknown intent or tool plan');
 if(!Number.isInteger(s.retry_count)||s.retry_count<0||s.retry_count>1) throw Error('Invalid retry count');
 if(s.tools.includes('image_search')&&!x.has_image) throw Error('Image intent requires an upload');
 if(s.tools.includes('report_search')&&!s.question) throw Error('Report intent requires a question');
 if(s.intent!=='metadata_lookup' && Object.keys(s.filters).some(k=>!['split','modality'].includes(k))) throw Error('Structured metadata filters require metadata_lookup');
 if(s.intent==='report_question' && s.filters.modality) throw Error('Modality filtering applies to images or metadata');
} catch(e) {s.status='invalid_request';s.errors.push(e.message);s.intent='out_of_scope_or_insufficient';s.tools=[];s.needs_generation=false;}
s.trace.push('allowlist_plan_validation');
return [{json:x}];

const items=$input.all().map(x=>x.json);
if(items.length!==2 || new Set(items.map(x=>x.kind)).size!==2 || items.some(x=>!['report','image'].includes(x.kind)||!x.job_id||x.state.request_id!==items[0].state.request_id)) throw Error('Invalid paired retrieval jobs');
return [{json:{state:items.find(x=>x.kind==='report').state,jobs:items.map(x=>x.job_id)}}];

const s=$input.first().json.state;
s.registry=[];
const seen=new Set();
for(const [kind,rows] of [['report',s.reports],['image',s.images]]) for(const row of rows) {
 const id=kind==='report'?row.passage_id:row.image_id;
 if(!id||!row.patient_id||row.split!=='train'||(s.patient_id&&row.patient_id===s.patient_id)||seen.has(kind+id)) {s.errors.push('Invalid evidence identity or patient/split leakage');continue;}
 seen.add(kind+id);
 s.registry.push({kind,id,patient_id:row.patient_id,source:kind==='report'?row.source:row.source_image_reference,split:row.split,modality:row.modality??null,rank:row.rank,similarity:row.similarity??null});
}
s.trace.push('assemble_evidence_registry');
return [{json:{state:s}}];

const s=$input.first().json.state;
if(s.retry_count!==0 || !s.tools.includes('report_search') || s.errors.length) throw Error('Retry limit or tool constraint violated');
s.retry_count=1;
s.query=(s.question+' OPINION explicit annual follow up close follow up BI-RADS').slice(0,2200);
s.reports=[];s.registry=[];s.generation_evidence=[];s.candidate_answer='';s.answer=null;s.citations=[];
s.checker={decision:'not_checked',problems:[],checked_passage_ids:[]};
s.trace.push('targeted_query_rewrite_retry_1_of_1');
return [{json:{state:s}}];

const s=JSON.parse(JSON.stringify($input.first().json.state ?? $('Validate allowlisted plan').first().json.state));
s.status='tool_error';
s.errors.push('local_tool_transport_failed');
s.trace.push('local_tool_transport_failed');
s.answer=null;s.citations=[];
return [{json:{state:s}}];

const s=$input.first().json.state;
let status=s.status;
if(s.errors.length) status=s.status==='invalid_request'?'invalid_request':'tool_error';
else if(s.intent==='out_of_scope_or_insufficient') status='out_of_scope';
else if(s.intent==='metadata_lookup') status=s.metadata.length?'ok':'not_found';
else if(s.checker.decision==='accept'&&s.answer) status='answered';
else if(s.checker.decision==='sufficient'&&!s.needs_generation) status='retrieved';
else status='abstained';
const accepted=status==='answered';
return [{json:{request_id:s.request_id,intent:s.intent,status,query_patient_id:s.patient_id,answer:accepted?s.answer:null,citations:accepted?s.citations:[],sources:s.registry,report_passages:s.reports,similar_images:s.images,metadata:s.metadata,tools_called:s.tools_called,retry_count:s.retry_count,checker:s.checker,generation_passage_ids:s.generation_evidence.map(r=>r.passage_id),limitations:[...new Set(s.limitations)],errors:s.errors,trace:s.trace}}];
